from decimal import Decimal, InvalidOperation
from fractions import Fraction

def _has_at_most_2dp(amount: Decimal) -> bool:
    if amount.is_zero():
        return True
    t = amount.as_tuple()
    exp = t.exponent
    if exp >= -2:
        return True
    need = -exp - 2
    digits = t.digits
    if len(digits) <= need:
        return False
    for d in digits[len(digits) - need:]:
        if d != 0:
            return False
    return True

def _cents_exact(abs_amount: Decimal) -> int:
    if abs_amount.is_zero():
        return 0
    t = abs_amount.as_tuple()
    exp = t.exponent
    s = "".join(str(d) for d in t.digits)
    D = int(s) if s else 0
    shift = exp + 2
    if shift >= 0:
        return D * (10 ** shift)
    else:
        div = 10 ** (-shift)
        return D // div

def allocate_by_ratios(total: str, ratios: list) -> list[Decimal]:
    if not isinstance(total, str):
        raise ValueError("total must be a string")
    try:
        amount = Decimal(total)
    except (InvalidOperation, ValueError):
        raise ValueError(f"invalid total: {total!r}") from None
    if not amount.is_finite():
        raise ValueError("total must be finite")
    if not _has_at_most_2dp(amount):
        raise ValueError("total must have at most 2 decimal places")
    if not isinstance(ratios, list) or len(ratios) == 0:
        raise ValueError("ratios must be a non-empty list")
    weights = []
    for entry in ratios:
        if isinstance(entry, bool):
            raise ValueError("bool weights are not accepted")
        if isinstance(entry, int):
            weight = Decimal(entry)
        elif isinstance(entry, Decimal):
            weight = entry
        elif isinstance(entry, str):
            try:
                weight = Decimal(entry)
            except (InvalidOperation, ValueError):
                raise ValueError(f"invalid weight: {entry!r}") from None
        else:
            raise ValueError(f"invalid weight: {entry!r}")
        if not weight.is_finite():
            raise ValueError("weights must be finite")
        if weight < 0:
            raise ValueError("weights must be >= 0")
        weights.append(weight)
    frac_weights = [Fraction(w) for w in weights]
    total_weight = sum(frac_weights, Fraction(0))
    if total_weight <= 0:
        raise ValueError("at least one weight must be > 0")
    negative = amount < 0
    cents = _cents_exact(abs(amount))
    floors = []
    remainders = []
    for fw in frac_weights:
        if fw == 0:
            floors.append(0)
            remainders.append(Fraction(0))
        else:
            exact = Fraction(cents) * fw / total_weight
            fl = exact.numerator // exact.denominator
            floors.append(int(fl))
            remainders.append(exact - fl)
    remaining = cents - sum(floors)
    order = sorted((i for i, w in enumerate(frac_weights) if w > 0), key=lambda i: (-remainders[i], -frac_weights[i], i))
    for i in order[:remaining]:
        floors[i] += 1
    parts = []
    for f in floors:
        if f == 0:
            part = Decimal("0.00")
        else:
            dollars = f // 100
            cc = f % 100
            part = Decimal(f"{dollars}.{cc:02d}")
            if negative:
                part = -part
        parts.append(part)
    return parts
